/**
 * S2：全站 UI 文案唯一真源。
 *
 * 【为什么要有这个文件】
 * 之前界面文字散落在 15 个组件的 template / script 里，直接导致两个真问题：
 *   1. **同一句话写了不止一遍**——「练习开始啦喵～」曾同时存在于 LessonDetailView 与
 *      RightPanel，「代码已经叼到剪贴板里啦喵～」同时存在于 LessonDetailView 与 CompareGrid。
 *      改一处忘一处，界面就会出现两种说法。
 *   2. **界面文案没人管**——docs/04 §8.1 的语尾规则是写给课文散文的，
 *      界面按钮、空状态、报错一直散在各处，既无统一说法、也无处统一修改。
 *
 * 【改文案的唯一姿势】
 * 只改本文件。不要在组件里直接写面向用户的中文串——
 * `__tests__/copy.test.ts` 会扫描渲染层源码里的字符串字面量，写死中文会让单测变红。
 * 例外：仅给开发者看的注释不算文案。
 *
 * 【本文件遵守的规则】docs/04 §8（§8.1 语尾密度、§8.2 反面清单、§8.3 界面文案）：
 *   - 信息该说清楚的必须说清楚，猫咪口吻是包装不是替代（§8.2 结尾）
 *   - 空状态成对出现：一行说「没什么」，一行说「你该怎么办」（§8.3）
 *   - 确认类弹窗必须讲清「会丢什么」，不能只问一句「确定吗」（§8.3）
 *
 * 注：语尾密度（≤20%）是**课文**指标，见 scripts/content-validate.mjs；
 * 界面短文案句数太少，统计密度没有意义，故不适用。
 */

