// ──────────────────────────────────────────────────────────── 动态演示（demo 块）

/**
 * 演示播放器的全部文案。
 *
 * 【为什么作者没写标题时给一句默认的，而不是留空】
 * 卡片顶上有没有字，决定了它是一个「块」还是一个「悬在正文里的东西」。
 * 留空的话，播放器的按钮行会孤零零贴着上一段正文，看不出这是另一个部件。
 *
 * 【为什么按钮上要带图标还要带字】
 * 只有 `⏮ ▶ ⏭` 三个符号的播放器，第一次见的人得挨个点一遍才知道哪个是哪个。
 * 这是教学软件：**看不懂控件的成本，比多占几十像素高得多**。
 */
export const DEMO = {
  /** 作者没写 `title:` 时用它 */
  DEFAULT_TITLE: '动态演示',
  /** 回到第 1 步 */
  PREV: '⏮ 上一步',
  /** 开始自动播放 */
  PLAY: '▶ 播放',
  /** 播放中：同一个按钮变成暂停，停在**当前这一步的终态** */
  PAUSE: '⏸ 暂停',
  /** 前进 1 步 */
  NEXT: '下一步 ⏭',
  /** 步骤计数：`第 3 / 12 步` */
  stepCounter: (at: number, total: number): string => `第 ${at} / ${total} 步`,
  /** 变量区的小标题 */
  VARS_TITLE: '这一刻的值',
  /** 一步都没有变量时，在变量区说一句实话，而不是留一片空白 */
  NO_VARS: '这一步还没有变量',
  /** 演示块的注释标签（和「复制」一样是块级小按钮那一带的说明文字） */
  BADGE: '逐步演示',
  /**
   * 气泡那句短话的**说话人标签**（2026-09-20 加）。
   *
   * 屏幕上它是一行小字，读屏软件念出来时也是它 ——
   * 一句话得先知道是谁说的，才读得懂它是讲解还是打岔。
   * 它同时是这一格的无障碍名字：没有它，读屏用户会听到一句
   * 悬空的话，不知道从哪儿冒出来的。
   */
  MEOW_ROLE: '大肥鱼说',
  /**
   * 气泡旁边那张立绘的**默认**姿态。
   *
   * 【为什么不在这里逐个步骤写姿态】
   * 姿态**跟着步骤走**：作者在课文里给某一步写 `pose: think`，那一步就想想事情的脸。
   * 播放器不按规则猜姿势（和 `meow` 同一条理由：一推断就替教学内容下判断了）。
   * 所以这个值只负责**兜底** —— 作者这一步没写 `pose:` 时用它，
   * 以及老课文（一个 `pose:` 都没有）逐字节维持原样。
   *
   * 【为什么写在文案表里，而不是在组件里写死】
   * 「换一张什么样的脸」和「换一句什么话」是同一件事的两半 ——
   * 都是这个角色的表情。分成两个地方，调表情时就得先想「它在哪个文件里」。
   * 取值必须是 `lib/mascot.ts` 的 `MASCOT_POSES` 里的一个（类型会拦住写错的）。
   * 课文里那份 `pose:` 由 `content-validate.mjs` 用同一张表把关。
   */
  MEOW_POSE: 'yay'
} as const

