// ──────────────────────────────────────────────────────────── 三栏布局壳

/**
 * 左栏 ☰ 那枚按钮的三态文案（open → rail → hidden 循环，见 shared/layout.ts
 * 的 sidebarTogglePatch），加右栏那一对。
 *
 * 分隔条上没有可见文字，这几句只会出现在 `title` 里 —— 但**一样得走这里**：
 * 哪天要统一说法（比如全改成「侧边栏」），它们不该是唯一漏网的那几句。
 *
 * 每个动作**分开写**，不拼串：中文里这些动作不是加个字就能互推的，
 * 硬拼出来的「收起辅助面板/展开辅助面板」看着对，换个动词就露馅。
 * 左栏三句各说「按下去会发生什么」：整栏→图标（RAIL_SIDEBAR）、
 * 图标→没有（HIDE_SIDEBAR）、没有→整栏（EXPAND_SIDEBAR）。
 * （原 COLLAPSE_SIDEBAR「收起侧边栏」v18 删：整栏态的下一站不再是「收起」
 * 而是 rail，那句文案已经没有对应的按钮状态了。）
 */
export const LAYOUT = {
  COLLAPSE_PANEL: '收起辅助面板',
  EXPAND_PANEL: '展开辅助面板',
  RAIL_SIDEBAR: '收成图标栏',
  HIDE_SIDEBAR: '隐藏侧边栏',
  EXPAND_SIDEBAR: '展开侧边栏'
} as const

// ──────────────────────────────────────────────────────────── 正文/代码缩放

/**
 * 缩放控件的五句话。
 *
 * 【为什么 TITLE 里要专门说一句「滚轮是滚动、不是缩放」】
 * 主人点名过一条红线：**滚轮绝不能改变缩放**。那么用户按下 Ctrl 滚一下、
 * 发现页面在滚而不是在缩，第一反应会是「坏了」。与其等他去试，
 * 不如把这句话挂在放大镜上 —— 这一个 `title` 省掉一次「是不是没做」的怀疑。
 * 后半句写的是**滚轮实际会做什么**，不是「不支持滚轮缩放」那种否定式说明。
 *
 * 【为什么「缩小/放大」是两句而不是给动词留个占位符】
 * 中文里这两个词不是「缩」+「小/大」能拼出来的，硬拼出来的东西换个语序就露馅。
 * 两句各写各的，将来想改成「调小一档」也只用改一处。
 */
export const ZOOM = {
  /** 放大镜图标的悬停提示 */
  TITLE: '缩放正文和代码喵（鼠标滚轮还是上下滚动，不会改变缩放）',
  OUT: '缩小一点',
  IN: '放大一点',
  RESET: '点一下回到 100%',
  /** 滑块的读屏标签 —— 它没有可见文字，只能靠这一句说明自己是什么 */
  SLIDER: '拖动滑块调整正文和代码的大小'
} as const

