// ──────────────────────────────────────────────────────────── 收藏页（学习闭环 §6）

/**
 * 收藏页的全部文案：左筛选栏、列表、多选工具条、文件夹管理。
 *
 * 【两个容易混的「全部」】
 * `ALL` 是筛选器的"这一维不筛"，出现在**四个维度**里；
 * 空态那条 `FAVORITES_FILTERED_EMPTY` 说的也是它。它们必须用同一个词 ——
 * 一个叫「全部」一个叫「不限」的话，用户会以为那是两个不同的动作。
 *
 * 【为什么「其他来源」要单独一档】
 * `FavoriteItem.source` 是**选填**的：手改过的文件、将来从别处导入的文件
 * 都可能没有它。没有不等于"别的"，但界面上必须有个地方放它们 ——
 * 藏起来的话那几条收藏会在来源筛选里**永远看不见**（types.ts 里那段
 * 选填的理由就是这么写的：留空、由界面归进「其他」）。
 */
