/**
 * 备忘录页的全部文案：工具条、左栏列表、右栏编辑器。
 *
 * 【两个分类的名字是「纯代码 / 知识性备忘」不是「代码 / 知识」】
 * 分类徽章贴在列表行上，旁边就是标题 —— 写「代码」的话，一条写着
 * `list.index` 的备忘会显示成「代码 · 代码」（标题里本来就常常带"代码"两个字）。
 * 「纯代码」把"这一条整个就是一段代码"说清楚，和「知识性备忘」（一句话记个知识点）
 * 正好是一对反义的说法，用户第一次看也分得清该往哪边放。
 *
 * 分类就两档是**有意**的（见 types.ts 的 MemoKind）：分类多了，新建时选哪档
 * 就成了一个要犹豫的问题，而犹豫的代价是用户干脆不分类 —— 两档是
 * "用户愿意顺手点一下"的上限。
 */
export const MEMO = {
  /** 左栏分类 chips 与右栏分类切换共用这三句（同一个概念不许两个词） */
  KIND_ALL: '全部',
  KIND_CODE: '纯代码',
  KIND_KNOWLEDGE: '知识性备忘',

  /** 新建按钮 */
  NEW: '新建备忘',
  /** 工具条搜索框 */
  SEARCH_PH: '搜索标题或正文',
  /** 编辑器两个输入框 */
  TITLE_PH: '标题',
  BODY_PH: '正文…',

  /** 删除按钮（V1-32 起点一下直接删，确认框已按主人裁定拆除） */
  DELETE: '删除',

  /** 正文的字节计数（右栏底部那行） */
  SIZE: (kb: string): string => `正文 ${kb} / 64 KB`,
  /**
   * 超长拦截时的提示。
   *
   * 【为什么给"拆成两条"这个去处】只说"太长了"等于把用户晾在原地：
   * 他手上那段东西必须有个地方放。而且**不能写"已自动截断"** ——
   * 我们一个字都没截，是他自己删掉多余部分才能存（如实说）。
   */
  TOO_LONG: '这条太长了（单条上限 64KB），拆成两条吧'
} as const

